#include SOURCE
#include "types.hpp"
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <utility>
#include <vector>
int main(int argc,char**argv){
 if(argc!=4)return 1;
 const int n=std::atoi(argv[1]),mode=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 using T=VALUE;using UF=UnionFindW<T>;std::mt19937 rng(61022);
 std::vector<std::pair<int,int>> balanced,star,randoms,queries;
 std::vector<T> potential;for(int i=0;i<n;++i)potential.emplace_back(i%1000);
 auto gap=[&](int a,int b){return potential[b]-potential[a];};
 for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)balanced.emplace_back(i,i+step);
 for(int i=1;i<n;++i)star.emplace_back(0,i);
 for(int i=0;i<n;++i){randoms.emplace_back(int(rng()%n),int(rng()%n));queries.emplace_back(int(rng()%n),int(rng()%n));}
 UF uf(n),initial(n);
 if(mode==2||mode==4||mode==5||mode==8||mode==9||mode==10||mode==11||mode==12||mode==13)for(auto[a,b]:balanced){uf.unite(a,b,gap(a,b));initial.unite(a,b,gap(a,b));}
 if(mode==3||mode==7)for(int i=0;i<n;i+=4)for(int j=1;j<4&&i+j<n;++j)uf.unite(i,i+j,gap(i,i+j));
 std::uint64_t checksum=0;
 const auto query=[&](UF& target){for(auto[a,b]:queries){auto d=target.try_diff(a,b);checksum+=d?checksum_value(*d):1;}};
 const auto run=[&](){
  if(mode<=1||mode==14){UF local(n);const auto&edges=mode==0?balanced:mode==1?star:randoms;for(auto[a,b]:edges)checksum+=local.constrain(a,b,gap(a,b));query(local);checksum+=local.component_count();}
  else if(mode==2||mode==3)query(uf);
  else if(mode==4){for(auto[a,b]:queries)checksum+=uf.same(a,b);}
  else if(mode==5){for(auto[a,b]:queries)checksum+=uf.constrain(a,b,gap(a,b)+T(1));}
  else if(mode>=6&&mode<=8){auto groups=uf.groups();checksum+=groups.size();for(const auto&g:groups)checksum+=g.size()+static_cast<unsigned>(g.back());}
  else if(mode==9){UF local=initial;auto groups=local.groups();query(local);checksum+=groups.size();}
  else if(mode==10){for(auto[a,b]:queries)checksum+=checksum_value(uf.weight(a))+checksum_value(uf.diff(a,b));}
  else if(mode==11){for(int i=0;i<n;++i)checksum+=checksum_value(*uf.try_diff(i,i));}
  else if(mode==12){UF copy=initial;checksum+=copy.component_count();}
  else if(mode==13){for(auto[a,b]:queries)checksum+=uf.merge(a,b,gap(a,b));}
 };
 run();checksum=0;
 const auto begin=std::chrono::steady_clock::now();for(int r=0;r<reps;++r)run();const auto end=std::chrono::steady_clock::now();
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),static_cast<std::uintmax_t>(checksum));
}

