#include SOURCE
#include "types.hpp"
#include <algorithm>
#include <cstdio>
#include <optional>
#include <queue>
#include <random>
#include <stdexcept>
#include <vector>
std::uint64_t checks=0;
void ck(bool b){++checks;if(!b)throw std::runtime_error("weighted reference mismatch");}
template<class T>void run(){
 const int n=24;UnionFindW<T> uf(n);std::vector<std::vector<std::pair<int,T>>> graph(n);std::vector<int> label(n);for(int i=0;i<n;++i)label[i]=i;std::mt19937 rng(61022);
 const auto difference=[&](int s,int t)->std::optional<T>{std::vector<bool> seen(n);std::vector<T> weight(n);std::queue<int> q;q.push(s);seen[s]=true;while(!q.empty()){int v=q.front();q.pop();if(v==t)return weight[v];for(auto[u,w]:graph[v])if(!seen[u]){seen[u]=true;weight[u]=weight[v]+w;q.push(u);}}return std::nullopt;};
 for(int it=0;it<2500;++it){int a=int(rng()%n),b=int(rng()%n),op=int(rng()%4);T w(static_cast<int>(rng()%31)-15);auto d=difference(a,b);
  if(op<3){if(op==0)ck(uf.merge(a,b,w)==!d);else if(op==1){uf.unite(a,b,w);}else ck(uf.constrain(a,b,w)==(!d||*d==w));
   if(!d){int x=label[a],y=label[b];int nx=int(std::count(label.begin(),label.end(),x)),ny=int(std::count(label.begin(),label.end(),y));if(nx<ny)std::swap(x,y);for(int&i:label)if(i==y)i=x;graph[a].emplace_back(b,w);graph[b].emplace_back(a,T{}-w);}}
  for(int k=0;k<8;++k){a=int(rng()%n);b=int(rng()%n);d=difference(a,b);ck(uf.root(a)==label[a]);ck(uf.leader(a)==label[a]);ck(uf.same(a,b)==bool(d));ck(uf.try_diff(a,b)==d);if(d)ck(uf.diff(a,b)==*d);ck(uf.weight(a)==*difference(label[a],a));ck(uf.size(a)==std::count(label.begin(),label.end(),label[a]));}
  if(it%71==0){auto groups=uf.groups();int total=0,oldroot=-1;for(const auto&g:groups){ck(std::is_sorted(g.begin(),g.end()));ck(label[g.front()]>oldroot);oldroot=label[g.front()];for(int v:g){ck(label[v]==label[g.front()]);++total;}}ck(total==n);ck(static_cast<int>(groups.size())==uf.component_count());auto cp=uf;ck(cp.diff(a,a)==T{});}
  if(it%251==0){uf=UnionFindW<T>(n);graph.assign(n,{});for(int i=0;i<n;++i)label[i]=i;}
 }
}
int main(){run<std::int64_t>();run<std::uint64_t>();run<Mod>();run<Ring>();
#ifndef SKIP_SMALL_UNSIGNED
 run<std::uint8_t>();UnionFindW<std::uint8_t> u(3);u.unite(0,1,250);u.unite(0,2,5);ck(u.constrain(1,2,11));
#endif
 std::printf("PASS checks=%ju\n",static_cast<std::uintmax_t>(checks));}

