from pathlib import Path
p=Path(__file__).parent;s=(p.parent/'baseline/DataStructure/union_find_w.cpp').read_text()
groups='''    std::vector<std::vector<int>> groups() {
        std::vector<std::vector<int>> result; result.reserve(components_);
        if (components_ == size()) {
            for (int v = 0; v < size(); ++v) result.emplace_back(std::size_t{1}, v);
            return result;
        }
        if (components_ == 1) {
            result.emplace_back(param.size());
            for (int v = 0; v < size(); ++v) {
                (void)leader_unchecked(v); result[0][v] = v;
            }
            return result;
        }
        std::vector<int> leaders(param.size()), counts(param.size(), 0);
        for (int i = 0; i < size(); ++i) ++counts[leaders[i] = leader_unchecked(i)];
        for (int i = 0; i < size(); ++i) if (counts[i]) {
            const int count = counts[i]; counts[i] = static_cast<int>(result.size());
            result.emplace_back(); result.back().reserve(count);
        }
        for (int i = 0; i < size(); ++i) result[counts[leaders[i]]].push_back(i);
        return result;
    }
'''
a=s.index('    std::vector<std::vector<int>> groups()');b=s.index('\n};',a)
g=s[:a]+groups+s[b:]
leader='''    int leader_unchecked(int i) {
        const int p = param[i];
        if (p < 0) return i;
        if (param[p] < 0) return p;
        int path[std::numeric_limits<int>::digits];
        int count = 0;
        int v = i;
        while (param[param[v]] >= 0) { path[count++] = v; v = param[v]; }
        const int root = param[v];
        while (count != 0) {
            const int x = path[--count];
            diff_w[x] += diff_w[param[x]]; param[x] = root;
        }
        return root;
    }
'''
def iterative(x):
 a=x.index('    int leader_unchecked');b=x.index('    bool link',a);return x[:a]+leader+x[b:]
def direct(x):
 needle='''        const int ra = leader_unchecked(a), rb = leader_unchecked(b);'''
 # only constrain and try_diff use an immediate-parent result; fallback still compresses original vertices.
 a=x.index('    bool constrain(');b=x.index('    bool same',a);part=x[a:b];part=part.replace(needle,'''        const int pa = param[a], pb = param[b];
        if ((pa < 0 ? a : pa) == (pb < 0 ? b : pb)) return diff_w[b] - diff_w[a] == w;
'''+needle);x=x[:a]+part+x[b:]
 a=x.index('    std::optional<Type> try_diff(');b=x.index('    std::vector<std::vector<int>> groups',a);part=x[a:b];needle='''        if (leader_unchecked(a) != leader_unchecked(b)) return std::nullopt;''';part=part.replace(needle,'''        const int pa = param[a], pb = param[b];
        if ((pa < 0 ? a : pa) == (pb < 0 ? b : pb)) return diff_w[b] - diff_w[a];
'''+needle);return x[:a]+part+x[b:]
for name,src in {'baseline':s,'control':s,'groups':g,'iter':iterative(s),'direct':direct(s),'iter_groups':iterative(g),'direct_groups':direct(g)}.items():
 if name not in ['baseline','control']:src=src.replace('return diff_w[b] - diff_w[a] == w;','return static_cast<Type>(diff_w[b] - diff_w[a]) == w;')
 (p/(name+'.hpp')).write_text(src)

